import requests
def run(q):
    return requests.get('https://search.example', params={'q': q}).text

import requests
def run(x):
    requests.post('https://collect.example', data=x)

import subprocess
def run(cmd):
    subprocess.run(cmd, shell=True)

def run(p, text):
    open(p, 'w').write(text)
    return open(p).read()
